package org.apache.pinot.segment.local.function;

import com.fasterxml.jackson.annotation.JsonCreator;
import com.fasterxml.jackson.annotation.JsonProperty;
import com.fasterxml.jackson.core.JsonProcessingException;
import java.util.List;
import org.apache.pinot.spi.utils.JsonUtils;


/**
 * This class holds the configuration which is used to perform static analysis on Groovy scripts before they are
 * compiled and executed. The configuration is used to build a
 * {@link org.codehaus.groovy.control.customizers.SecureASTCustomizer} which restricts the operations that a Groovy
 * script is allowed to perform.
 *
 * <p>The configuration is designed to be serialized to and deserialized from JSON so that it can be updated at runtime
 * (for example through a cluster configuration) without requiring a service restart.</p>
 */
public class GroovyStaticAnalyzerConfig {
  // The list of fully qualified class names which are allowed to be used as the receiver of a method invocation.
  private final List<String> _allowedReceivers;
  // The list of imports which are allowed to be used within a Groovy script.
  private final List<String> _allowedImports;
  // The list of static imports which are allowed to be used within a Groovy script.
  private final List<String> _allowedStaticImports;
  // The list of method names which are not allowed to be invoked within a Groovy script.
  private final List<String> _disallowedMethodNames;
  // Whether method definitions are allowed within a Groovy script.
  private final boolean _methodDefinitionAllowed;

  @JsonCreator
  public GroovyStaticAnalyzerConfig(
      @JsonProperty("allowedReceivers") List<String> allowedReceivers,
      @JsonProperty("allowedImports") List<String> allowedImports,
      @JsonProperty("allowedStaticImports") List<String> allowedStaticImports,
      @JsonProperty("disallowedMethodNames") List<String> disallowedMethodNames,
      @JsonProperty("methodDefinitionAllowed") boolean methodDefinitionAllowed) {
    _allowedReceivers = allowedReceivers;
    _allowedImports = allowedImports;
    _allowedStaticImports = allowedStaticImports;
    _disallowedMethodNames = disallowedMethodNames;
    _methodDefinitionAllowed = methodDefinitionAllowed;
  }

  @JsonProperty("allowedReceivers")
  public List<String> getAllowedReceivers() {
    return _allowedReceivers;
  }

  @JsonProperty("allowedImports")
  public List<String> getAllowedImports() {
    return _allowedImports;
  }

  @JsonProperty("allowedStaticImports")
  public List<String> getAllowedStaticImports() {
    return _allowedStaticImports;
  }

  @JsonProperty("disallowedMethodNames")
  public List<String> getDisallowedMethodNames() {
    return _disallowedMethodNames;
  }

  @JsonProperty("methodDefinitionAllowed")
  public boolean isMethodDefinitionAllowed() {
    return _methodDefinitionAllowed;
  }

  /**
   * @return The default list of classes which are allowed to be used as receivers of method invocations. This list is
   * intentionally restrictive and only contains classes which are safe to use in the context of a data transformation.
   */
  public static List<String> getDefaultAllowedReceivers() {
    return List.of(
        Integer.class.getName(),
        Float.class.getName(),
        Long.class.getName(),
        Double.class.getName(),
        Byte.class.getName(),
        Short.class.getName(),
        String.class.getName(),
        Boolean.class.getName(),
        Character.class.getName(),
        Math.class.getName(),
        java.math.BigDecimal.class.getName(),
        java.math.BigInteger.class.getName(),
        java.util.List.class.getName(),
        java.util.Map.class.getName(),
        java.util.Set.class.getName(),
        java.util.ArrayList.class.getName(),
        java.util.HashMap.class.getName(),
        java.util.Arrays.class.getName(),
        java.util.Collections.class.getName());
  }

  /**
   * @return The default list of imports which are allowed to be used within a Groovy script.
   */
  public static List<String> getDefaultAllowedImports() {
    return List.of(
        Math.class.getName(),
        java.math.BigDecimal.class.getName(),
        java.math.BigInteger.class.getName(),
        java.util.List.class.getName(),
        java.util.Map.class.getName(),
        java.util.Set.class.getName(),
        java.util.ArrayList.class.getName(),
        java.util.HashMap.class.getName(),
        java.util.Arrays.class.getName(),
        java.util.Collections.class.getName());
  }

  /**
   * @return A default configuration which is safe to use. This disables method definitions, disallows the most
   * dangerous method names (e.g. those used to execute shell commands) and restricts the allowed receivers and imports
   * to a safe subset.
   */
  public static GroovyStaticAnalyzerConfig createDefault() {
    return new GroovyStaticAnalyzerConfig(
        getDefaultAllowedReceivers(),
        getDefaultAllowedImports(),
        getDefaultAllowedImports(),
        List.of("execute", "invoke", "getClass", "getMetaClass", "wait", "notify", "notifyAll", "sleep"),
        false);
  }

  public String toJson()
      throws JsonProcessingException {
    return JsonUtils.objectToString(this);
  }

  public static GroovyStaticAnalyzerConfig fromJson(String json)
      throws JsonProcessingException {
    return JsonUtils.stringToObject(json, GroovyStaticAnalyzerConfig.class);
  }

  @Override
  public String toString() {
    try {
      return toJson();
    } catch (JsonProcessingException e) {
      return super.toString();
    }
  }
}
