148	    SecureASTCustomizer customizer = new SecureASTCustomizer();
149	    // Control whether Groovy scripts are allowed to define their own methods.
150	    customizer.setMethodDefinitionAllowed(config.isMethodDefinitionAllowed());
151	    // Restrict which imports and static imports can be used.
152	    if (config.getAllowedImports() != null) {
153	      customizer.setImportsWhitelist(config.getAllowedImports());
154	    }
155	    if (config.getAllowedStaticImports() != null) {
156	      customizer.setStaticImportsWhitelist(config.getAllowedStaticImports());
157	    }
158	    // Restrict which classes can be used as the receiver of a method invocation.
159	    if (config.getAllowedReceivers() != null) {
160	      customizer.setReceiversWhiteList(config.getAllowedReceivers());
161	    }
162	    // Reject any method invocation whose name is on the disallowed list. This is used to block dangerous methods such
163	    // as those which execute shell commands (e.g. String#execute()).
164	    List<String> disallowedMethodNames = config.getDisallowedMethodNames();
165	    if (disallowedMethodNames != null && !disallowedMethodNames.isEmpty()) {
166	      customizer.addExpressionCheckers((SecureASTCustomizer.ExpressionChecker) expression -> {
167	        if (expression instanceof MethodCallExpression) {
168	          String methodName = ((MethodCallExpression) expression).getMethodAsString();
169	          return methodName == null || !disallowedMethodNames.contains(methodName);
170	        }
171	        return true;
172	      });
173	    }
174	    return customizer;
175	  }
