+import groovy.lang.Binding;
+import groovy.lang.GroovyShell;
+import java.util.List;
+import org.codehaus.groovy.ast.expr.MethodCallExpression;
+import org.codehaus.groovy.control.CompilerConfiguration;
+import org.codehaus.groovy.control.customizers.SecureASTCustomizer;
+
+public class GTest {
+  static List<String> receivers = List.of("java.lang.Integer","java.lang.Long","java.lang.Double","java.lang.String","java.lang.Math","java.util.List","java.util.Map","java.util.ArrayList","java.util.HashMap");
+  static List<String> imports = List.of("java.lang.Math","java.util.List","java.util.Map","java.util.ArrayList","java.util.HashMap");
+  static List<String> disallowed = List.of("execute","invoke","getClass","sleep");
+
+  static SecureASTCustomizer make() {
+    SecureASTCustomizer c = new SecureASTCustomizer();
+    c.setMethodDefinitionAllowed(false);
+    c.setImportsWhitelist(imports);
+    c.setStaticImportsWhitelist(imports);
+    c.setIndirectImportCheckEnabled(true);
+    c.setReceiversWhiteList(receivers);
+    c.addExpressionCheckers((SecureASTCustomizer.ExpressionChecker) e -> {
+      if (e instanceof MethodCallExpression) {
+        String m = ((MethodCallExpression)e).getMethodAsString();
+        return m == null || !disallowed.contains(m);
+      }
+      return true;
+    });
+    return c;
+  }
+
+  static void tryScript(String label, String script) {
+    try {
+      CompilerConfiguration cc = new CompilerConfiguration();
+      cc.addCompilationCustomizers(make());
+      new GroovyShell(new Binding(), cc).parse(script);
+      System.out.println("PARSED OK  : " + label);
+    } catch (Exception ex) {
+      System.out.println("REJECTED   : " + label + "  -> " + ex.getClass().getSimpleName() + ": " + ex.getMessage().replaceAll("\n"," ").substring(0, Math.min(90, ex.getMessage().length())));
+    }
+  }
+
+  public static void main(String[] a) {
+    tryScript("benign concat", "arg0 + \" \" + arg1");
+    tryScript("benign math", "Math.max(arg0, arg1)");
+    tryScript("shell exec", "\"ls\".execute()");
+    tryScript("runtime exec", "Runtime.getRuntime().exec(\"ls\")");
+    tryScript("string method toUpperCase", "arg0.toUpperCase()");
+    tryScript("import bad", "import java.io.File; new File(\"/\").listFiles()");
+  }
+}
