@@ -0,0 +1,48 @@
+import org.apache.pinot.segment.local.function.GroovyStaticAnalyzerConfig;
+import org.apache.pinot.segment.local.function.GroovyFunctionEvaluator;
+
+public class V {
+  static void expectReject(String s) {
+    try { GroovyFunctionEvaluator.parseGroovyScript(s); System.out.println("FAIL (not rejected): " + s); }
+    catch (Exception e) { System.out.println("OK rejected: " + s.substring(0, Math.min(40,s.length()))); }
+  }
+  static void expectOk(String s) {
+    try { GroovyFunctionEvaluator.parseGroovyScript(s); System.out.println("OK parsed: " + s.substring(0, Math.min(40,s.length()))); }
+    catch (Exception e) { System.out.println("FAIL (rejected benign): " + s + " -> " + e.getMessage()); }
+  }
+  public static void main(String[] a) throws Exception {
+    // 1. JSON round-trip
+    GroovyStaticAnalyzerConfig def = GroovyStaticAnalyzerConfig.createDefault();
+    String json = def.toJson();
+    System.out.println("JSON: " + json);
+    GroovyStaticAnalyzerConfig back = GroovyStaticAnalyzerConfig.fromJson(json);
+    boolean ok = back.getAllowedReceivers().equals(def.getAllowedReceivers())
+        && back.getAllowedImports().equals(def.getAllowedImports())
+        && back.getAllowedStaticImports().equals(def.getAllowedStaticImports())
+        && back.getDisallowedMethodNames().equals(def.getDisallowedMethodNames())
+        && back.isMethodDefinitionAllowed() == def.isMethodDefinitionAllowed();
+    System.out.println("JSON round-trip lossless: " + ok);
+
+    // null preservation
+    GroovyStaticAnalyzerConfig nulls = new GroovyStaticAnalyzerConfig(null, null, null, null, false);
+    System.out.println("null preserved: " + (nulls.getAllowedReceivers()==null && nulls.getDisallowedMethodNames()==null));
+
+    // 2. No config set -> analysis disabled, everything parses
+    System.out.println("--- no config (analysis off) ---");
+    expectOk("Groovy({\"ls\".execute()})");
+
+    // 3. Set default config -> malicious rejected, benign ok
+    GroovyFunctionEvaluator.setGroovyStaticAnalyzerConfig(def);
+    System.out.println("--- default config active ---");
+    expectReject("Groovy({\"ls\".execute()})");
+    expectReject("Groovy({Runtime.getRuntime().exec(\"ls\")})");
+    expectReject("Groovy({[\"bash\",\"-c\",\"ls\"].execute()})");
+    expectOk("Groovy({arg0 + \" \" + arg1})");
+    expectOk("Groovy({Math.max(arg0, arg1)})");
+
+    // 4. Runtime change: clear config -> now allowed again (no restart)
+    GroovyFunctionEvaluator.setGroovyStaticAnalyzerConfig(null);
+    System.out.println("--- config cleared at runtime ---");
+    expectOk("Groovy({\"ls\".execute()})");
+  }
+}
